<?php if(!isset($workData)){http_response_code(403);exit;} $workTypes=employment_options(positive_id($workData['hubungan_kerja_id'])??null); ?>
<fieldset><legend>Status kerja dan mulai bekerja</legend><p>Lolos seleksi belum berarti sudah bekerja. Pilih Sudah mulai bekerja hanya setelah benar-benar mulai; lengkapi seluruh data kerja.</p>
<label for="status_kerja">Status kerja<select id="status_kerja" name="status_kerja" required><option value="belum_bekerja" <?= $workData['status_kerja']==='belum_bekerja'?'selected':'' ?>>Belum mulai bekerja</option><option value="sudah_bekerja" <?= $workData['status_kerja']==='sudah_bekerja'?'selected':'' ?>>Sudah mulai bekerja</option></select></label>
<?php foreach(['kerja_perusahaan'=>['Perusahaan tempat bekerja',200],'kerja_posisi'=>['Posisi kerja',200],'tanggal_mulai_kerja'=>['Tanggal mulai bekerja',10]] as $key=>[$label,$max]): ?><label for="<?= $key ?>"><?= e($label) ?><input id="<?= $key ?>" name="<?= $key ?>" type="<?= $key==='tanggal_mulai_kerja'?'date':'text' ?>" maxlength="<?= $max ?>" value="<?= e($workData[$key]) ?>"></label><?php endforeach; ?>
<label for="hubungan_kerja_id">Jenis hubungan kerja<select id="hubungan_kerja_id" name="hubungan_kerja_id"><option value="">Pilih jenis</option><?php foreach($workTypes as $type): ?><option value="<?= $type['id'] ?>" <?= (string)$type['id']===$workData['hubungan_kerja_id']?'selected':'' ?>><?= e($type['nama'].(!$type['aktif']?' (nonaktif)':'')) ?></option><?php endforeach; ?></select></label></fieldset>
